import { afterEach, describe, expect, it, vi } from 'vitest';
import { resetCsrfToken } from '@dwp-frontend/shared-utils/axios-instance';
import { HttpTransportError } from '@dwp-frontend/shared-utils';

import { getHrisPayrollWorkspace } from './payroll-api';

function jsonResponse(data: unknown): Response {
  return {
    ok: true,
    status: 200,
    text: async () => JSON.stringify({ data }),
  } as Response;
}

describe('getHrisPayrollWorkspace', () => {
  afterEach(() => {
    resetCsrfToken();
    vi.unstubAllGlobals();
  });

  it('binds the personal HR scope to the Gateway GET', async () => {
    const response = { employee: { personId: 'person-1' }, statements: [] };
    const fetchMock = vi.fn().mockResolvedValue(jsonResponse(response));
    vi.stubGlobal('fetch', fetchMock);
    const controller = new AbortController();

    await expect(
      getHrisPayrollWorkspace('scope:hcm/personal-pay', controller.signal)
    ).resolves.toEqual(response);

    expect(fetchMock).toHaveBeenCalledOnce();
    expect(fetchMock.mock.calls[0]?.[0]).toBe(
      '/api/people/v1/hr/pay?contextScopeKey=scope%3Ahcm%2Fpersonal-pay'
    );
    expect((fetchMock.mock.calls[0]?.[1] as RequestInit).signal).toBeInstanceOf(AbortSignal);
  });

  it('propagates React Query cancellation to the active Gateway request', async () => {
    const fetchMock = vi.fn(
      (_url: string, init?: RequestInit) =>
        new Promise<Response>((_resolve, reject) => {
          init?.signal?.addEventListener('abort', () => {
            reject(new DOMException('The operation was aborted.', 'AbortError'));
          });
        })
    );
    vi.stubGlobal('fetch', fetchMock);
    const controller = new AbortController();

    const request = getHrisPayrollWorkspace('scope:hcm/personal-pay', controller.signal).then(
      () => undefined,
      (error: unknown) => error
    );
    controller.abort('scope-changed');

    await expect(request).resolves.toEqual(expect.any(HttpTransportError));
    await expect(request).resolves.toMatchObject({ reason: 'ABORT' });
    expect(fetchMock.mock.calls[0]?.[1]?.signal?.aborted).toBe(true);
  });
});

import { axiosInstance } from '@dwp-frontend/shared-utils/axios-instance';
import { productSurfaceReadScopeConfig } from '@dwp-frontend/shared-utils/api/product-surface-read-scope';

import type { ApiResponse, HrPayWorkspace } from '@dwp-frontend/shared-utils';

export const HRIS_PAYROLL_WORKSPACE_API_PATH = '/api/people/v1/hr/pay' as const;

export async function getHrisPayrollWorkspace(
  contextScopeKey: string | undefined,
  signal: AbortSignal
): Promise<HrPayWorkspace> {
  const response = await axiosInstance.get<ApiResponse<HrPayWorkspace>>(
    HRIS_PAYROLL_WORKSPACE_API_PATH,
    productSurfaceReadScopeConfig(contextScopeKey, signal)
  );
  return response.data.data;
}

import { useQuery } from '@tanstack/react-query';

import { useProductSurfaceRequestScope } from '../../../../components/use-product-surface-request-scope';
import { getHrisPayrollWorkspace } from '../api/payroll-api';
import { buildPayrollSelfServiceModel } from '../model/payroll-self-service-model';

export function useHrisPayrollWorkspace() {
  const requestScope = useProductSurfaceRequestScope({
    productKey: 'hcm',
    surfaceKey: 'hcm.personal',
  });
  const query = useQuery({
    queryKey: ['hcm', 'pay', ...requestScope.cacheKey],
    queryFn: async ({ signal }) => {
      const source = await getHrisPayrollWorkspace(requestScope.contextScopeKey, signal);
      return buildPayrollSelfServiceModel(source);
    },
    enabled: requestScope.ready,
    meta: requestScope.queryMeta,
    staleTime: 60_000,
  });

  return {
    ready: requestScope.ready,
    authorityKey: JSON.stringify(requestScope.cacheKey),
    model: query.data,
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    retry: () => void query.refetch(),
  };
}

