    let oldSignal: AbortSignal | undefined;
    let nextSignal: AbortSignal | undefined;
    vi.mocked(getHrisPayrollWorkspace).mockImplementation((contextScopeKey, signal) => {
      if (contextScopeKey === 'scope-personal-a') {
        oldSignal = signal;
