      nextSignal = signal;
      return nextResponse.promise;
    });

    await renderWorkspace();
    const oldScope = scopeRuntime.current!;
    expect(
      queryClient.getQueryCache().find({
        queryKey: ['hcm', 'pay', ...oldScope.cacheKey],
